"use strict";(function($){var acf=window.acf;var pdlACFData=window.pdlACFData;if(typeof acf==="undefined"){console.warn("acf.js not loaded.");return}if(typeof pdlACFData==="undefined"){console.warn("pdl-acf.js not localized properly.");return}var pdlACF=window.pdlACF={collegesFieldKey:"field_611279af182d2",departmentsFieldKey:"field_630fb69367bc5",departmentLoaded:null,collegesDepartments:{},prepareCollege:function prepareCollege(field){field.$el.on("select2:select",function(e){pdlACF.collegeSet(e.params.data.id)})},loadDepartment:function loadDepartment(field){var college=acf.getField(pdlACF.collegesFieldKey);if(field.val()&&!pdlACF.departmentLoaded){pdlACF.departmentLoaded=Number(field.val())}if(!college.val()){field.disable()}else{field.enable();pdlACF.collegeSet(college.val())}},collegeSet:function collegeSet(collegeID){if(typeof pdlACF.collegesDepartments[collegeID]!=="undefined"){pdlACF.setDepartments(pdlACF.collegesDepartments[collegeID])}else{$.post(pdlACFData.ajax_url,{_ajax_nonce:pdlACFData.nonce,action:"get_college_departments",college:collegeID},function(data){pdlACF.collegesDepartments[collegeID]=data;pdlACF.setDepartments(data)})}},setDepartments:function setDepartments(newOptions){var field=acf.getField(pdlACF.departmentsFieldKey);var $select=$("select",field.$el);$select.val(null).empty();if(typeof newOptions!=="undefined"){if(newOptions.length){$select.append(new Option(field.data.placeholder,0,false,false));newOptions.forEach(function(opt){var selected=opt.term_id===pdlACF.departmentLoaded;$select.append(new Option(opt.name,opt.term_id,selected,selected))});field.enable()}else{$select.append(new Option(pdlACFData.label_not_found,0));field.disable()}}}};acf.addAction("prepare_field/key="+pdlACF.collegesFieldKey,pdlACF.prepareCollege);acf.addAction("load_field/key="+pdlACF.departmentsFieldKey,pdlACF.loadDepartment)})(window.jQuery);
